INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 25, 'theory', 'Quiz: libvirt-python');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 0, 'How does a domain''s shutdown method differ from destroy?', '["shutdown pulls the power, destroy asks the guest to power off", "They are equivalent and differ only in name", "shutdown only sends the guest a request and returns at once, destroy ends it immediately", "shutdown deletes the domain definition, destroy keeps it"]', 2, 'shutdown is a request to the guest (which may ignore it), so you poll the state until a deadline. destroy is like pulling the power cord: the disks may be left inconsistent. The definition is removed by undefine.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 1, 'What is the most reliable way for a script to recognise a ''no such domain'' error?', '["Compare get_error_code() with VIR_ERR_NO_DOMAIN (42)", "Look for the words ''not found'' in the exception text", "Check the exception type: it is always a KeyError", "Call isActive() before lookupByName"]', 0, 'Every failure arrives as libvirtError, and the numeric code tells them apart. The message text is for people and changes between versions and languages. isActive() cannot be called before the domain is found.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 2, 'How do you get a domain''s CPU load as a percentage of its vCPUs?', '["Take cpuTime from info() and divide by the vCPU count", "Read a ready ''cpu_percent'' field from info()", "Divide cpuTime by the domain''s memory size", "Take the cpuTime growth over an interval and divide by (elapsed nanoseconds x vCPU count)"]', 3, 'cpuTime is a cumulative counter in nanoseconds, so you need two readings and their difference, divided by the elapsed time and the vCPU count. info() has no ready percentage.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 3, 'What must be done about the libvirt event loop in Python?', '["Nothing: events arrive on their own once domainEventRegisterAny is called", "Register an implementation before opening the connection and run virEventRunDefaultImpl in a loop", "Call virEventRunDefaultImpl once after closing the connection", "Run the loop only from inside an event callback"]', 1, 'The loop implementation is registered before the connection is opened, and virEventRunDefaultImpl is then called in a loop, usually in a daemon thread. Without it the callbacks never run, and the connection may be closed by the keepalive timeout.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 25, 4, 'Which key in the getAllDomainStats dictionary holds the bytes written to the first disk?', '["disk.0.written", "block.1.wr.bytes", "block.0.wr.bytes", "blockStats.wr_bytes"]', 2, 'Arrays are numbered from zero, and the key is block.<index>.wr.bytes, with the number of disks in block.count. block.1 is already the second disk.');
